head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자

// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00400_04.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 결산일자 조회
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ConnObjMajTrd_OnLoadError
 * @description dts_ConnObjMajTrd 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ConnObjMajTrd_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ConnObjMajTrd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00400_04.dts_ConnObjMajTrd_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ConnObjMajTrd_OnLoadCompleted
 * @description dts_ConnObjMajTrd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ConnObjMajTrd_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ConnObjMajTrd.errorMsg) {
            await $c.win.alert(dts_ConnObjMajTrd.errorMsg);
        }

        // 멀티Row의 데이터를 하나로 합치자.
        scwin.appendContents();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00400_04.dts_ConnObjMajTrd_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 연결대상간주요거래  조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ConnObjMajTrd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ConnObjMajTrd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_ConnObjMajTrd.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name appendContents
 * @description 컨텐츠 append
 * @returns {void}
 * @hidden N
 */
scwin.appendContents = function() {
    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:575px;font-family:돋움체;'>";
    for (let nRow = 1; nRow <= dts_ConnObjMajTrd.getRowCount(); nRow++) {
        strContent = strContent + dts_ConnObjMajTrd.getCellData(nRow, "CTNT") + "";
    }
    strContent = strContent + "</div>";
    pan_Ctnt.innerHTML = strContent;

    // 태그 제거후 &nbsp; 만 남는경우 조회된 데이터가 없습니다를 뿌려준다
    // 임시방편으로 만든것 NICE 신용평가에 요청해야 함
    const pattern = /<[^>]+>/g;
    const pan_Ctnt_text = strContent.replace(pattern, '');
    if ($c.stf.trim(pan_Ctnt_text) === "&nbsp;") {
    } else {
    }
};
